public class Order {
    private OrderItemManager itemManager;
    private OrderStatusManager statusManager;

    public Order() {
        this.itemManager = new OrderItemManager();
        this.statusManager = new OrderStatusManager();
    }

    public void addItem(String name, int quantity, double price) {
        itemManager.addItem(name, quantity, price);
    }

    public String getStatus() {
        return statusManager.getStatus();
    }

    public void setStatus(String status) {
        statusManager.setStatus(status);
    }
}

public class OrderItemManager {
    private List<String> items;
    private List<Integer> quantities;
    private List<Double> prices;

    public OrderItemManager() {
        this.items = new ArrayList<>();
        this.quantities = new ArrayList<>();
        this.prices = new ArrayList<>();
    }

    public void addItem(String name, int quantity, double price) {
        this.items.add(name);
        this.quantities.add(quantity);
        this.prices.add(price);
    }
    // Additional methods for managing items can be added here
}

public class OrderStatusManager {
    private String status;

    public OrderStatusManager() {
        this.status = "open";
    }

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }
}
